"use strict";(globalThis.webpackChunksap_architecture_center=globalThis.webpackChunksap_architecture_center||[]).push([[75165],{83427(e){e.exports=JSON.parse('{"tag":{"label":"Reference Architectures","permalink":"/docs/tags/ref-arch","description":"Reference Architectures offer standardized, reusable templates for software architecture, providing best practices, guidelines, and blueprints to streamline design, development, and deployment.","allTagsPath":"/docs/tags","count":9,"items":[{"id":"ref-arch/RA0031/id-ra0031","title":"Decentralized Identity Verification","description":"Decentralized Identity Verification (DIV) is a multi-tenant SAP BTP service that enables enterprise applications to use Self-Sovereign Identity (SSI) for secure, privacy-preserving inter-company communications.","permalink":"/docs/ref-arch/08N_yhbT"},{"id":"ref-arch/RA0031/bring-your-own-wallet/id-ra0031-2","title":"DIV \u2013 Bring Your Own Wallet","description":"Bring Your Own Wallet (BYOW) describes the provisioning model in which a dataspace member self-provisions SAP DIV on SAP BTP instead of receiving a wallet from the Operating Company. The operator still issues the membership credential, which is pushed to the member-hosted DIV wallet.","permalink":"/docs/ref-arch/08N_yhbT/2"},{"id":"ref-arch/RA0031/product-carbon-footprint-use-case/id-ra0031-3","title":"DIV \u2013 Product Carbon Footprint Use Case","description":"This reference architecture describes how SAP Decentralized Identity Verification (DIV) enables secure, privacy-preserving exchange of Product Carbon Footprint (PCF) data between supply chain partners using Self-Sovereign Identity and Verifiable Credentials, with each member provisioning their own DIV wallet (Bring Your Own Wallet).","permalink":"/docs/ref-arch/08N_yhbT/3"},{"id":"ref-arch/RA0031/vc-issuance-and-verification/id-ra0031-1","title":"DIV \u2013 Verifiable Credential Issuance and Verification","description":"This reference architecture describes how SAP Decentralized Identity Verification (DIV) issues, signs, and verifies W3C Verifiable Credentials and Verifiable Presentations on SAP BTP.","permalink":"/docs/ref-arch/08N_yhbT/1"},{"id":"ref-arch/RA0027/id-ra0027","title":"Log-Driven Security Operations with SAP Enterprise Threat Detection and SIEM/SOAR Platforms","description":"This reference architecture shows how SAP Enterprise Threat Detection provides log-driven security signals that are correlated in FortiSIEM and orchestrated through FortiSOAR to enable centralized monitoring incident investigation and automated response.","permalink":"/docs/ref-arch/d6e703646d"},{"id":"ref-arch/RA0025/sap-pi-po-to-integration-suite/id-ra0025-1","title":"Migrating from SAP Process Integration/Orchestration to SAP Integration Suite","description":"Learn about the transition from SAP Process Integration (PI) and Process Orchestration (PO) to SAP Integration Suite, an iPaaS solution for modern integration needs. Discover benefits, migration tools, architectural shifts, and strategies for simplifying integration landscapes and reducing TCO.","permalink":"/docs/ref-arch/9a5f7b59dc/1"},{"id":"ref-arch/id-intro-0","title":"SAP Reference Architecture - Building Blocks for Business Success","description":"Learn how to utilize SAP reference architectures for building efficient, scalable, and secure enterprise solutions. Adopt proven patterns using SAP BTP, cloud integration, and industry standards for digital transformation.","permalink":"/docs/ref-arch"},{"id":"ref-arch/RA0028/id-ra0028","title":"SAP SuccessFactors Suite","description":"Overview of the SAP SuccessFactors modules and how data flows between them","permalink":"/docs/ref-arch/5Hlvofqg"},{"id":"ref-arch/RA0025/id-ra0025","title":"Transitioning Architectures from SAP NetWeaver","description":"Discover how SAP customers can transition from NetWeaver-based products approaching end-of-maintenance in 2027. Explore successor solutions, integration strategies, innovation needs, and security considerations for seamless migration and future-proofing your SAP landscape.","permalink":"/docs/ref-arch/9a5f7b59dc"}],"unlisted":false}}')}}]);